false,"defaultMatch":false,"display":true,"type":"dateTime","readOnly":false,"removed":false},{"id":"expediteur","displayName":"expediteur","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"categorie","displayName":"categorie","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"resume","displayName":"resume","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"auto_envoye","displayName":"auto_envoye","required":false,"defaultMatch":false,"display":true,"type":"boolean","readOnly":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[1568,240],"id":"122b45a3-88b0-46be-be02-8b79a661cf3f","name":"Insert row"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f001","leftValue":"={{ $json.categorie }}","rightValue":"spam","operator":{"type":"string","operation":"notEquals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.filter","typeVersion":2.2,"position":[1344,0],"id":"f1a1b111-0000-4000-8000-000000000010","name":"Filtrer spam"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f002","leftValue":"={{ $json.auto_envoi_possible }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,432],"id":"f1a1b111-0000-4000-8000-000000000011","name":"Auto-envoi possible ?"},{"parameters":{"resource":"email","operation":"send","fromEmail":"v.caufriez@ebanista.fr","toEmail":"={{ $